/* void UpdateTexture(Texture2D texture, const void * pixels) */
static Janet jrl_cfun_UpdateTexture(int32_t argc, Janet *argv) {
    janet_fixarity(argc, 2);
    Texture2D texture = *(Texture2D *) jrl_get_handle(argv, 0, &jrl_type_Texture);
    JanetByteView jrl_v_pixels = jrl_get_bytes(argv, 1, 0);
    const void* pixels = (const void*) jrl_v_pixels.bytes;
    if (jrl_v_pixels.bytes != NULL && jrl_v_pixels.len < (int32_t) (GetPixelDataSize(texture.width, texture.height, texture.format)))
        janet_panicf("argument %d: expected at least %d bytes, got %d", 1, (int32_t) (GetPixelDataSize(texture.width, texture.height, texture.format)), jrl_v_pixels.len);
    UpdateTexture(texture, pixels);
    return janet_wrap_nil();
}

/* void UpdateTextureRec(Texture2D texture, Rectangle rec, const void * pixels) */
static Janet jrl_cfun_UpdateTextureRec(int32_t argc, Janet *argv) {
    janet_fixarity(argc, 3);
    Texture2D texture = *(Texture2D *) jrl_get_handle(argv, 0, &jrl_type_Texture);
    Rectangle rec;
    jrl_get_value(argv, 1, &jrl_type_Rectangle, &rec);
    JanetByteView jrl_v_pixels = jrl_get_bytes(argv, 2, 0);
    const void* pixels = (const void*) jrl_v_pixels.bytes;
    if (jrl_v_pixels.bytes != NULL && jrl_v_pixels.len < (int32_t) (GetPixelDataSize((int)rec.width, (int)rec.height, texture.format)))
        janet_panicf("argument %d: expected at least %d bytes, got %d", 2, (int32_t) (GetPixelDataSize((int)rec.width, (int)rec.height, texture.format)), jrl_v_pixels.len);
    UpdateTextureRec(texture, rec, pixels);
    return janet_wrap_nil();
}

