/* GlyphInfo * LoadFontData(const unsigned char * fileData, int dataSize, int fontSize, int * codepoints, int codepointCount, int type) */
static Janet jrl_cfun_LoadFontData(int32_t argc, Janet *argv) {
    janet_fixarity(argc, 4);
    int dataSize = 0;
    int fontSize = jrl_get_int(argv, 1);
    int codepointCount = 0;
    int type = (int) jrl_get_enum(argv, 3, &jrl_enum_FontType);
    JanetByteView jrl_v_fileData = jrl_get_bytes(argv, 0, 0);
    const unsigned char* fileData = (const unsigned char*) jrl_v_fileData.bytes;
    dataSize = jrl_v_fileData.len;
    int32_t jrl_n_codepoints = 0;
    int* codepoints = (int*) jrl_get_carray(argv, 2, JRL_K_INT, NULL, NULL, 1, 0, &jrl_n_codepoints);
    codepointCount = jrl_n_codepoints;
    GlyphInfo* jrl_ret = LoadFontData(fileData, dataSize, fontSize, codepoints, codepointCount, type);
    Janet jrl_value = (jrl_ret ? jrl_array_owned(JRL_K_TYPE, &jrl_type_GlyphInfo, jrl_ret, (int32_t) ((codepointCount > 0) ? codepointCount : 95)) : janet_wrap_nil());
    if (codepoints) janet_sfree((void *) codepoints);
    return jrl_value;
}

