/* void UpdateSound(Sound sound, const void * data, int sampleCount) */
static Janet jrl_cfun_UpdateSound(int32_t argc, Janet *argv) {
    janet_fixarity(argc, 3);
    Sound sound = *(Sound *) jrl_get_handle(argv, 0, &jrl_type_Sound);
    int sampleCount = jrl_get_int(argv, 2);
    JanetByteView jrl_v_data = jrl_get_bytes(argv, 1, 0);
    const void* data = (const void*) jrl_v_data.bytes;
    if (jrl_v_data.bytes != NULL && jrl_v_data.len < (int32_t) (sampleCount * sound.stream.channels * (sound.stream.sampleSize / 8)))
        janet_panicf("argument %d: expected at least %d bytes, got %d", 1, (int32_t) (sampleCount * sound.stream.channels * (sound.stream.sampleSize / 8)), jrl_v_data.len);
    UpdateSound(sound, data, sampleCount);
    return janet_wrap_nil();
}

