/* void UpdateAudioStream(AudioStream stream, const void * data, int frameCount) */
static Janet jrl_cfun_UpdateAudioStream(int32_t argc, Janet *argv) {
    janet_fixarity(argc, 3);
    AudioStream stream = *(AudioStream *) jrl_get_handle(argv, 0, &jrl_type_AudioStream);
    int frameCount = jrl_get_int(argv, 2);
    JanetByteView jrl_v_data = jrl_get_bytes(argv, 1, 0);
    const void* data = (const void*) jrl_v_data.bytes;
    if (jrl_v_data.bytes != NULL && jrl_v_data.len < (int32_t) (frameCount * stream.channels * (stream.sampleSize / 8)))
        janet_panicf("argument %d: expected at least %d bytes, got %d", 1, (int32_t) (frameCount * stream.channels * (stream.sampleSize / 8)), jrl_v_data.len);
    UpdateAudioStream(stream, data, frameCount);
    return janet_wrap_nil();
}

